#!/usr/bin/env node
// apply-rules.mjs — generated by /composure:initialize (step 08d) from the plugin's template.
// Run by you, the user: `! node scripts/composure/apply-rules.mjs`
//
// Writes the files the agent may not write (rules.json and the checker are protected), all of them
// from the installed Composure plugin:
//   .composure/rules.json            resolved from the plugin defaults + this project's stack
//   .composure/bin/composure-check.mjs   the checker, committed so every verdict comes from the same bytes
//   .composure/no-bandaids.json      loses disabledRules / skipPatterns / frameworkValidation (they live in
//                                    rules.json "overrides" now); every other key is left alone
//   .claude/settings.json            one Stop hook entry; the rest of your hooks are not touched
//   .github/workflows/composure-check.yml   the CI check (GitHub projects, only when absent)
// (No Codex Stop adapter yet: its command form has not been verified on a live host. The commit gate and CI
// still enforce the same rules.)
//
// Re-run safe: "overrides" in an existing rules.json survive (a payload group you deleted stays deleted, recorded
// in overrides.removed), an unchanged file is reported as unchanged, and a second run changes nothing. Everything is
// validated before the first write: a rule that cannot run, a legacy key of the wrong type, or a legacy group that
// differs from the one already in rules.json stops the run with nothing written and nothing deleted. It resolves its
// project from its own location (two levels up), never from the working directory. It imports nothing from the
// project or the plugin: the plugin is found at run time (--plugin <dir>, COMPOSURE_PLUGIN_ROOT, or the native
// install at ~/.composure/marketplace/plugins/composure) and its checker does the resolving.
//
// Flags: --plugin <dir> | --plugin=<dir>   --force (allow an older plugin than the one that wrote rules.json)
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync, chmodSync } from "node:fs"
import { homedir, tmpdir } from "node:os"
import { dirname, join, resolve } from "node:path"
import { fileURLToPath } from "node:url"
import { spawnSync } from "node:child_process"
import { isDeepStrictEqual } from "node:util"

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..")
// Project rules the initialize run generated (step 08's anti-pattern scan). Same shape as the old
// no-bandaids.json "frameworkValidation": { "<group>": { "appliesTo": [...], "rules": [...] } }.
const PAYLOAD = {"frameworkValidation": {"sparehold-bash-32": {"appliesTo": ["**/*.sh", "*.sh"], "rules": [{"name": "assoc-array-bash4", "pattern": "\\bdeclare\\s+-A\\b", "severity": "error", "message": "Associative arrays need bash 4+; this suite must run under the system /bin/bash 3.2 (AGENTS.md). Gate the script behind a version check that re-execs or skips, as memory-auto-clean.sh does."}, {"name": "mapfile-bash4", "pattern": "\\bmapfile\\b|\\breadarray\\b", "severity": "error", "message": "mapfile/readarray need bash 4+; the suite must run under /bin/bash 3.2 (AGENTS.md). Use a while-read loop instead."}]}, "sparehold-ui-traps": {"appliesTo": ["**/*.swift", "*.swift"], "rules": [{"name": "hard-edge-trap", "pattern": "\\.scrollEdgeEffectStyle\\(\\.hard\\)", "severity": "error", "message": "UI trap (v2.7.1): the hard edge paints an opaque backdrop that fights the Settings window. Do not use it in this app."}, {"name": "list-section-spacing", "pattern": "\\.listSectionSpacing", "severity": "error", "message": "iOS-only modifier (AGENTS.md UI traps); it does not apply on macOS."}, {"name": "swift-warning-marker", "pattern": "#warning\\(", "severity": "error", "message": "Warnings are defects in this repo (AGENTS.md): fix the cause, never defer one with #warning."}]}}} // payload: sparehold bash-3.2 guard + v2.7.1 UI traps + swift #warning

// The Stop adapter. Claude runs a project hook with the directory it was LAUNCHED from as its working directory and as
// CLAUDE_PROJECT_DIR (probed 2026-11-18: from a subdirectory both a relative path and ${CLAUDE_PROJECT_DIR} point at the
// subdirectory, and the check silently never ran). So the command finds the committed checker by walking up from the
// working directory, and hands over stdin and the exit status unchanged. Node only (no shell, no git): it runs the same on
// macOS, Linux and Windows.
const ADAPTER_JS =
  'const fs=require("fs"),p=require("path");let h=require("os").homedir();try{h=fs.realpathSync(h)}catch(e){}let d=process.cwd(),f;' +
  'for(;;){const c=p.join(d,".composure","bin","composure-check.mjs");' +
  'if(d!==h&&fs.existsSync(c)){f=c;break}' +
  'if(fs.existsSync(p.join(d,".git"))||p.dirname(d)===d){process.stderr.write("composure-check: .composure/bin/composure-check.mjs not found in the repository containing "+process.cwd()+"; the commit gate and CI still check\\n");process.exit(0)}d=p.dirname(d)}' +
  'const r=require("child_process").spawnSync(process.execPath,[f,"hook","claude"],{stdio:"inherit"});process.exit(r.status===null?1:r.status)'
const ADAPTER_TIMEOUT = 5 // seconds. Measured 2026-11-18 (macOS, warm): median 215 ms, max 363 ms over 12 runs on a 60-file repo (__tests__/apply-rules-adapter.test.mjs); the checker alone is 235 ms median on a 5,000-file repo. Headroom is for a cold Windows node start (twice: the walker, then the checker).

const rel = (p) => p.slice(ROOT.length + 1).split("\\").join("/")
const isObject = (v) => v !== null && typeof v === "object" && !Array.isArray(v)
let failed = false
const say = (s) => console.log(s)
const refuse = (s) => { failed = true; console.error(s) }
const stop = (s) => { console.error(s); process.exit(1) }

// ── arguments ────────────────────────────────────────────────────────
let pluginArg
let force = false
{
  const argv = process.argv.slice(2)
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i]
    if (a === "--force") force = true
    else if (a === "--plugin") { pluginArg = argv[++i]; if (!pluginArg) stop("--plugin needs a directory") }
    else if (a.startsWith("--plugin=")) { pluginArg = a.slice("--plugin=".length); if (!pluginArg) stop("--plugin= needs a directory") }
    else stop(`unknown argument ${JSON.stringify(a)}. usage: node scripts/composure/apply-rules.mjs [--plugin <dir>] [--force]`)
  }
}

function pluginRoot() {
  const candidates = [pluginArg, process.env.COMPOSURE_PLUGIN_ROOT, join(homedir(), ".composure", "marketplace", "plugins", "composure")]
  for (const c of candidates) {
    if (c && existsSync(join(c, "hooks", "check", "composure-check.mjs")) && existsSync(join(c, "defaults"))) return resolve(c)
  }
  return null
}

function readJsonObject(file, what) {
  if (!existsSync(file)) return { exists: false, data: {} }
  let parsed
  try { parsed = JSON.parse(readFileSync(file, "utf8")) } catch { return { exists: true, data: null, error: `${what} is not valid JSON` } }
  return isObject(parsed) ? { exists: true, data: parsed } : { exists: true, data: null, error: `${what} is not a JSON object` }
}

const writeIfChanged = (file, text, mode) => {
  const before = existsSync(file) ? readFileSync(file, "utf8") : null
  if (before === text) return "unchanged"
  mkdirSync(dirname(file), { recursive: true })
  writeFileSync(file, text)
  if (mode) chmodSync(file, mode)
  return before === null ? "created" : "updated"
}
const json = (v) => JSON.stringify(v, null, 2) + "\n"
const semver = (v) => String(v ?? "").split("-")[0].split(".").map((n) => Number(n) || 0)
const olderThan = (a, b) => { const x = semver(a), y = semver(b); for (let i = 0; i < 3; i++) if ((x[i] ?? 0) !== (y[i] ?? 0)) return (x[i] ?? 0) < (y[i] ?? 0); return false }

const PLUGIN = pluginRoot()
if (!PLUGIN) stop("cannot find the Composure plugin (hooks/check/composure-check.mjs and defaults/). Pass --plugin <dir>, set COMPOSURE_PLUGIN_ROOT, or run /composure:sync first.")
const CHECKER_SRC = join(PLUGIN, "hooks", "check", "composure-check.mjs")
let pluginVersion = null
try { pluginVersion = JSON.parse(readFileSync(join(PLUGIN, ".claude-plugin", "plugin.json"), "utf8")).version ?? null } catch { /* the stack's own value is kept */ }
say(`plugin: ${PLUGIN} (version ${pluginVersion ?? "unknown"})`)

const node = (args, opts = {}) => spawnSync(process.execPath, args, { encoding: "utf8", maxBuffer: 64 * 1024 * 1024, ...opts })
const checkerVersion = /composure-check (\S+)/.exec(node([CHECKER_SRC, "version"]).stdout)?.[1] ?? null

// ── read and validate everything BEFORE the first write ──────────────
const STACK_FILE = join(ROOT, ".composure", "no-bandaids.json")
const RULES_FILE = join(ROOT, ".composure", "rules.json")
const stackRead = readJsonObject(STACK_FILE, rel(STACK_FILE))
if (!stackRead.exists) stop(`${rel(STACK_FILE)} does not exist: run /composure:initialize first.`)
if (!stackRead.data) stop(`refusing to continue: ${stackRead.error}. Fix it or move it aside, then run this again.`)
const existingRead = readJsonObject(RULES_FILE, rel(RULES_FILE))
if (existingRead.exists && !existingRead.data) stop(`refusing to continue: ${existingRead.error}. Move it aside and run this again.`)
const existing = existingRead.exists ? existingRead.data : null

// the three legacy keys must have the types the resolver reads
{
  const s = stackRead.data
  const bad = (k, why) => stop(`refusing to continue: ${rel(STACK_FILE)} "${k}" ${why}. Nothing was written. Fix it, then run this again.`)
  const strings = (v) => Array.isArray(v) && v.every((x) => typeof x === "string")
  if ("disabledRules" in s && !strings(s.disabledRules)) bad("disabledRules", "must be an array of rule names")
  if ("skipPatterns" in s && !strings(s.skipPatterns)) bad("skipPatterns", "must be an array of glob strings")
  if ("frameworkValidation" in s && !isObject(s.frameworkValidation)) bad("frameworkValidation", "must be an object of groups")
}

// a plugin older than the one that wrote rules.json would silently rewrite the rules and the checker older
if (existing && !force) {
  const wrote = existing.source?.composureVersion
  if ((wrote && pluginVersion && olderThan(pluginVersion, wrote)) || (existing.checker && checkerVersion && olderThan(checkerVersion, existing.checker))) {
    stop(`refusing to downgrade: rules.json was written by plugin ${wrote ?? "?"} / checker ${existing.checker ?? "?"}, this plugin is ${pluginVersion ?? "?"} / checker ${checkerVersion ?? "?"}. Point --plugin at the current plugin, or pass --force to downgrade on purpose.`)
  }
}

// payload groups: one the user deleted from rules.json stays deleted (recorded in overrides.removed)
const prevOverrides = existing?.overrides ?? {}
const applied = Array.isArray(prevOverrides.payload) ? prevOverrides.payload : []
const removed = [...new Set([...(Array.isArray(prevOverrides.removed) ? prevOverrides.removed : []), ...applied.filter((n) => !(n in (prevOverrides.groups ?? {})))])]
const payloadGroups = Object.fromEntries(Object.entries(PAYLOAD.frameworkValidation ?? {}).filter(([n]) => !removed.includes(n)))

const stack = { ...stackRead.data, ...(pluginVersion ? { composureVersion: pluginVersion } : {}), frameworkValidation: { ...payloadGroups, ...(isObject(stackRead.data.frameworkValidation) ? stackRead.data.frameworkValidation : {}) } }

function resolveWith(stackObj, withExisting) {
  const tmp = mkdtempSync(join(tmpdir(), "composure-rules-"))
  try {
    const stackTmp = join(tmp, "stack.json")
    writeFileSync(stackTmp, JSON.stringify(stackObj))
    const args = [CHECKER_SRC, "rules", "--resolve", "--stack", stackTmp, "--defaults", join(PLUGIN, "defaults")]
    if (withExisting && existing) args.push("--overrides", RULES_FILE)
    const r = node(args)
    if (r.status !== 0) stop(`the checker refused the rules (exit ${r.status}): ${(r.stderr || r.stdout || "").trim()}\nNothing was written and nothing was deleted.`)
    try { return JSON.parse(r.stdout) } catch { stop("the checker returned something that is not JSON; nothing written") }
  } finally {
    rmSync(tmp, { recursive: true, force: true })
  }
}
const resolved = resolveWith(stack, true)
if (resolved?.version !== 1 || !Array.isArray(resolved.groups)) stop("the resolved rules are not a version 1 rule set; nothing written")

// The legacy keys may be deleted only when rules.json will hold exactly what they say. Resolve them ALONE (no existing file)
// and compare content, not names: a group that is already in rules.json with different content wins the merge, and deleting
// the legacy copy would lose it.
const moved = ["disabledRules", "skipPatterns", "frameworkValidation"].filter((k) => k in stackRead.data)
if (moved.length) {
  const alone = resolveWith({ frameworkValidation: stackRead.data.frameworkValidation, disabledRules: stackRead.data.disabledRules, skipPatterns: stackRead.data.skipPatterns }, false).overrides
  const o = resolved.overrides ?? {}
  const missing = []
  for (const n of alone.disabled ?? []) if (!(o.disabled ?? []).includes(n)) missing.push(`disabledRules ${JSON.stringify(n)}`)
  for (const g of alone.skip ?? []) if (!(o.skip ?? []).includes(g)) missing.push(`skipPatterns ${JSON.stringify(g)}`)
  for (const [name, group] of Object.entries(alone.groups ?? {})) {
    if (!isDeepStrictEqual(group, (o.groups ?? {})[name])) missing.push(`frameworkValidation group ${JSON.stringify(name)} (rules.json holds ${name in (o.groups ?? {}) ? "a different group of that name" : "no such group"})`)
  }
  if (missing.length) {
    stop(`refusing to continue: ${rel(STACK_FILE)} still carries settings that rules.json would not hold:\n  ${missing.join("\n  ")}\nNothing was written and nothing was deleted. Reconcile the two (keep one version of each group), then run this again.`)
  }
}

// ── writes ───────────────────────────────────────────────────────────
const final = { ...resolved, overrides: { ...resolved.overrides, ...(removed.length ? { removed } : {}), ...(Object.keys(payloadGroups).length ? { payload: Object.keys(payloadGroups) } : {}) } }
say(`rules.json: ${writeIfChanged(RULES_FILE, json(final))}  (${final.groups.length} groups, checker ${final.checker})`)

if (moved.length) {
  const next = { ...stackRead.data }
  for (const k of moved) delete next[k]
  writeFileSync(STACK_FILE, json(next))
  say(`no-bandaids.json: moved ${moved.join(", ")} into rules.json overrides (all other keys untouched)`)
}

// the checker, byte for byte
const checker = readFileSync(CHECKER_SRC)
const CHECKER_DEST = join(ROOT, ".composure", "bin", "composure-check.mjs")
{
  const before = existsSync(CHECKER_DEST) ? readFileSync(CHECKER_DEST) : null
  if (before && before.equals(checker)) say("bin/composure-check.mjs: unchanged")
  else {
    mkdirSync(dirname(CHECKER_DEST), { recursive: true })
    writeFileSync(CHECKER_DEST, checker)
    chmodSync(CHECKER_DEST, 0o755)
    say(`bin/composure-check.mjs: ${before ? "updated" : "created"}  (${checker.subarray(0, checker.indexOf(10)).toString().replace(/^\/\/\s*/, "")})`)
  }
}

// Stop adapter — merge one entry into the host's own hooks file; never replace the file's other hooks.
const argsText = (h) => [h?.command, ...(Array.isArray(h?.args) ? h.args : [])].join(" ")
const isOurs = (h) => /composure-check\.mjs/.test(argsText(h)) && /\bhook\b/.test(argsText(h))
function mergeStop(file, entry, label) {
  const read = readJsonObject(file, rel(file))
  if (!read.data) { refuse(`${label}: NOT written. ${read.error}; fix it or move it aside and run this again.`); return }
  const cfg = read.data
  if (cfg.hooks !== undefined && !isObject(cfg.hooks)) { refuse(`${label}: NOT written. "hooks" is not an object in ${rel(file)}.`); return }
  const hooks = (cfg.hooks ??= {})
  if (hooks.Stop !== undefined && !Array.isArray(hooks.Stop)) { refuse(`${label}: NOT written. "hooks.Stop" is not an array in ${rel(file)}.`); return }
  const stopList = (hooks.Stop ??= [])
  let placed = false
  for (const group of stopList) {
    if (!Array.isArray(group?.hooks)) continue
    const i = group.hooks.findIndex(isOurs)
    if (i > -1) { group.hooks[i] = entry; placed = true; break }
  }
  if (!placed) stopList.push({ hooks: [entry] })
  say(`${label}: ${writeIfChanged(file, json(cfg))}  (${rel(file)} Stop)`)
}
mergeStop(join(ROOT, ".claude", "settings.json"), { type: "command", command: "node", args: ["-e", ADAPTER_JS], timeout: ADAPTER_TIMEOUT }, "claude adapter")
// Claude Code runs project-shared hooks only in a workspace it trusts (an untrusted `claude -p` ran none from .claude/settings.json).
say("codex adapter: Stop adapter pending probe: commit and CI still enforce")

// the CI workflow — a GitHub project, and only when it is absent (a workflow you edited stays yours)
const WORKFLOW_SRC = join(PLUGIN, "defaults", "ci", "composure-check.workflow.yml")
const WORKFLOW_DEST = join(ROOT, ".github", "workflows", "composure-check.yml")
const isGithub = (() => {
  if (existsSync(join(ROOT, ".github"))) return true
  const r = spawnSync("git", ["-C", ROOT, "remote", "get-url", "origin"], { encoding: "utf8" })
  return r.status === 0 && /github\.com/.test(r.stdout)
})()
if (!isGithub) say("ci workflow: skipped (not a GitHub project)")
else if (!existsSync(WORKFLOW_SRC)) say("ci workflow: skipped (this plugin version ships no composure-check workflow; /composure:sync updates the plugin)")
else if (existsSync(WORKFLOW_DEST)) say(`ci workflow: ${readFileSync(WORKFLOW_DEST, "utf8") === readFileSync(WORKFLOW_SRC, "utf8") ? "unchanged" : "left as is (it differs from the shipped template)"}`)
else say(`ci workflow: ${writeIfChanged(WORKFLOW_DEST, readFileSync(WORKFLOW_SRC, "utf8"))}  (${rel(WORKFLOW_DEST)})`)

say("commit these files: .composure/rules.json, .composure/bin/composure-check.mjs, .composure/no-bandaids.json, .claude/settings.json and the workflow.")
process.exit(failed ? 1 : 0)
